  const VIG_FS = ['uniform float strength; varying vec2 vUv;', 'void main(){', '  vec2 p = vUv - 0.5;', '  float d = dot(p, p);', '  float v = 1.0 - strength * smoothstep(0.12, 0.7, d);', '  gl_FragColor = vec4(vec3(v), 1.0);', '}'].join('\n');
