        const wallM = new THREE.MeshStandardMaterial({
          color: wallCol,
          roughness: 0.92,
          metalness: kind === 'warehouse' ? 0.2 : 0.05,
          side: THREE.DoubleSide
        });
        const mkWall = (w, x, z, ry) => {
          const ww = new THREE.Mesh(new THREE.BoxGeometry(w, wallH, 0.6), wallM);
          ww.position.set(x, wallH / 2, z);
          ww.rotation.y = ry;
          ww.receiveShadow = true;
          scene.add(ww);
        };
        mkWall(R * 2, 0, -R, 0);
        mkWall(R * 2, -R, 0, Math.PI / 2);
        mkWall(R * 2, R, 0, Math.PI / 2);
        if (kind === 'debug_grid' && THREE.GridHelper) {
          const grid = new THREE.GridHelper(R * 2, 30, 0x5ce0d8, 0x2a6f6a);
          if (grid.material) {
            grid.material.transparent = true;
            grid.material.opacity = 0.5;
            grid.material.fog = false;
          }
          grid.position.y = 0.05;
          scene.add(grid);
        }
