  // used in messages, the availability list and the assistant grounding.
  const PART_COMMAND = {
    ultrasonic: 'distance',
    imu: 'heading',
    line: 'on_line'
  };
  function partLabel(id) {
    return SENSORS[id] && SENSORS[id].name || ACTUATORS[id] && ACTUATORS[id].name || id;
  }
